// Issue 5704: Conversions of empty strings to byte
// or rune slices return empty but non-nil slices.

package main

type (
	mystring string
	mybytes  []byte
	myrunes  []rune
)

func checkBytes(s []byte, arg string) {
	if len(s) != 0 {
		panic("len(" + arg + ") != 0")
	}
	if s == nil {
		panic(arg + " == nil")
	}
}

func checkRunes(s []rune, arg string) {
	if len(s) != 0 {
		panic("len(" + arg + ") != 0")
	}
	if s == nil {
		panic(arg + " == nil")
	}
}

func main() {
	checkBytes([]byte(""), `[]byte("")`)
	checkBytes([]byte(mystring("")), `[]byte(mystring(""))`)
	checkBytes(mybytes(""), `mybytes("")`)
	checkBytes(mybytes(mystring("")), `mybytes(mystring(""))`)

	checkRunes([]rune(""), `[]rune("")`)
	checkRunes([]rune(mystring("")), `[]rune(mystring(""))`)
	checkRunes(myrunes(""), `myrunes("")`)
	checkRunes(myrunes(mystring("")), `myrunes(mystring(""))`)
}

// run
package main

import (
	"fmt"
	"runtime"
	"sort"
)

type node struct{ tag string }

var seen []string

// The object must become unreachable, so it is allocated in a helper whose
// frame is gone by the time the collector runs.
func drop(tag string) {
	n := &node{tag}
	runtime.SetFinalizer(n, func(p *node) { seen = append(seen, p.tag) })
}

func main() {
	for _, t := range []string{"alpha", "beta", "gamma"} {
		drop(t)
	}
	for i := 0; i < 4; i++ {
		runtime.GC()
	}
	sort.Strings(seen)
	fmt.Println("finalized:", len(seen), seen)

	off := &node{"off"}
	runtime.SetFinalizer(off, func(p *node) { fmt.Println("cleared finalizer ran") })
	runtime.SetFinalizer(off, nil)
	runtime.GC()

	live := &node{"live"}
	runtime.SetFinalizer(live, func(p *node) { fmt.Println("must not run", p.tag) })
	runtime.GC()
	runtime.GC()
	fmt.Println("still live:", live.tag)
	fmt.Println("done", off.tag)
}

// run
package main

import (
	"fmt"
	"runtime"
)

func main() {
	n := runtime.GOMAXPROCS(0)
	fmt.Println("default equals NumCPU:", n == runtime.NumCPU())
	prev := runtime.GOMAXPROCS(2)
	fmt.Println("previous returned:", prev == n)
	fmt.Println("now:", runtime.GOMAXPROCS(0))
	runtime.GOMAXPROCS(prev)
	fmt.Println("restored:", runtime.GOMAXPROCS(0) == n)
}

